const mutantLister = () =>
	(lister ??= TypeScriptMutationAdapter.open(repoRoot).then(
		(adapter): MutantLister => {
			const install = adapter.install();
			return {
				version: adapter.identity.toolVersion,
				source: adapter.source,
				packages: install.digest,
				identified: install.identified,
			};
		},
		(error: unknown): MutantLister => {
			if (error instanceof MutationEnumerationError && error.code === "instrumenter") return "unavailable";
			throw error;
		},
	));

#scan(directory: string, mode: Mode) {
	const seen = this.#entered.get(directory);
	// A directory npm lays out is one kind of place, so one reached as two, as a linked scope over a package is, is not.
	if (seen !== undefined && seen !== mode) this.#odd.push(this.#place(directory));
	if (seen !== undefined) return;
	if (this.#entered.size >= this.#limit)
		throw new InstalledPackagesError(
			`Melian cannot key its install: it holds more than ${this.#limit} directories.`,
		);
	this.#entered.set(directory, mode);
	if (directory.endsWith(".zip")) this.#odd.push(this.#place(directory));
	let entries: Dirent[];
	try {
		entries = readdirSync(directory, { withFileTypes: true });
	} catch {
		// A place the walk cannot read may hold anything, so the install it is in stands for no other.
		this.#odd.push(this.#place(directory));
		return;
	}
	if (mode === "package") {
		this.#packages.add(directory);
		this.#add(this.#place(directory), ...this.#release(directory));
	}
	for (const entry of entries) {
		const path = join(directory, entry.name);
		const slot = (mode === "modules" || mode === "scope") && !entry.name.startsWith(".");
		const child: Mode =
			slot && mode === "modules" && entry.name.startsWith("@")
				? "scope"
				: slot
					? "package"
					: entry.name === "node_modules"
						? "modules"
						: "tree";
		if (entry.isSymbolicLink()) this.#follow(path, child);
		else if (entry.isDirectory()) this.#scan(path, child);
	}
}

for (const [from, source] of [
	[join(repoRoot, "package.json"), "checkout"],
	[import.meta.url, "melian"],
] as const) {
	if (source === "checkout" && trackedInstall) continue;
	const require = createRequire(from);
	try {
		const module = await realpath(require.resolve("@stryker-mutator/instrumenter"));
		if (source === "checkout" && !inside(install, module)) continue;
		if (inside(root, module) && (!inside(install, module) || trackedInstall)) continue;
		if (
			source === "melian" &&
			!ancestorInstalls(fileURLToPath(import.meta.url)).some((directory) => inside(directory, module))
		)
			continue;
		if (!(await safeDependencies(module, root, install, trackedInstall))) continue;
		const { version } = JSON.parse(
			await readFile(require.resolve("@stryker-mutator/instrumenter/package.json"), "utf8"),
		) as { version: string };
		return new TypeScriptMutationAdapter(module, version, source);

